css = ['/* Minimalist line icons for titles, headings and subheadings. Add data-ic="<name>" to an element. Generated; edit tools/icons.py, then run: python3 tools/icons.py public/icons.css. */',
 '[data-ic]::before{content:"";display:inline-block;flex:none;width:1em;height:1em;margin-right:.42em;vertical-align:-.14em;background:currentColor;-webkit-mask:var(--ic) center/contain no-repeat;mask:var(--ic) center/contain no-repeat}',
 '.h1[data-ic]::before,.burst-title[data-ic]::before{width:.78em;height:.78em;vertical-align:-.04em;background:var(--accent)}',
 '.h2[data-ic]::before{width:.85em;height:.85em;background:var(--accent)}',
 '.eyebrow[data-ic]::before{width:1.25em;height:1.25em;vertical-align:-.3em;margin-right:.3em}',
 'legend [data-ic]::before,.box h3[data-ic]::before,.mcard h3>span[data-ic]::before,h3[data-ic]::before{background:var(--accent)}',
 '[data-ic-after]::after{content:none}']
for k, v in I.items():
    svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' + v + '</svg>'
    css.append('[data-ic="%s"]{--ic:url("data:image/svg+xml,%s")}' % (k, urllib.parse.quote(svg, safe=' =:/,.-')))
open(sys.argv[1], 'w').write("\n".join(css) + "\n")
print(len(I), "icons")
